 * Dependency-free ASAR extractor for the DSH checkout subtree.
 * Usage: node extract-asar.mjs <asarPath> <subtreePrefix> <destDir>
 */
import { openSync, readSync, readSync as rd, closeSync, mkdirSync, writeFileSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';

const [asarPath, prefix, destDir] = process.argv.slice(2);
if (!asarPath || !prefix || !destDir) {
  console.error('usage: node extract-asar.mjs <asarPath> <subtreePrefix> <destDir>');
  process.exit(2);
}

const fd = openSync(asarPath, 'r');
const head = Buffer.alloc(16);
readSync(fd, head, 0, 16, 0);
// ASAR: [UInt32 picklePayloadSize][UInt32 jsonSize][json][pad] then file blobs.
const payloadSize = head.readUInt32LE(0);
const jsonSize = head.readUInt32LE(4);
const jsonBuf = Buffer.alloc(jsonSize);
readSync(fd, jsonBuf, 0, jsonSize, 8);
const header = JSON.parse(jsonBuf.toString('utf8'));
// File blob offsets in the JSON are relative to the end of the header block:
// 8 bytes (both length fields) + payloadSize (payload is 4-aligned already).
const baseOffset = 8 + payloadSize;
console.log(`asar header ok: jsonSize=${jsonSize} baseOffset=${baseOffset}`);

let files = 0;
let dirs = 0;

function walk(node, relPath) {
  if (node.files) {
    for (const [name, child] of Object.entries(node.files)) {
      walk(child, relPath === '' ? name : `${relPath}/${name}`);
    }
    return;
  }
  if (node.offset === undefined || node.size === undefined) return; // link/unpacked marker
  if (!relPath.startsWith(prefix)) return;
  if (relPath.endsWith('/')) return;
  const start = baseOffset + Number(node.offset);
  const buf = Buffer.alloc(node.size);
  readSync(fd, buf, 0, node.size, start);
  const out = join(destDir, relPath.slice(prefix.length));
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, buf);
  files += 1;
}

function walkDirs(node, relPath) {
  if (node.files) {
    for (const [name, child] of Object.entries(node.files)) {
      walkDirs(child, relPath === '' ? name : `${relPath}/${name}`);
    }
  } else if (node.files === undefined && node.offset !== undefined) {
    if (relPath.startsWith(prefix)) dirs += 1;
  }
}

walkDirs(header, '');
walk(header, '');
closeSync(fd);
console.log(`matched ${dirs} files under "${prefix}", extracted ${files} to ${destDir}`);
"}

